struct Card: View {
    @Environment(\.colorScheme) var scheme
    var body: some View {
        Text(scheme == .dark ? "Dark" : "Light")
    }
}

struct Editor: View {
    @Environment(\.dismiss) var dismiss
    var body: some View {
        Button("Close") { dismiss() }
    }
}

struct Info: View {
    @Environment(\.locale) var locale
    var body: some View {
        Text(locale.identifier)
    }
}

